import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.springframework.boot.test.context.SpringBootTest;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

@SpringBootTest(classes = Application.class)
public class ItemsViewTest extends SpringBrowserlessTest {

    @BeforeEach
    void setup() {
        navigate(ItemsView.class);
    }

    @Test
    void initialState() {
        assertTrue($(H1.class).withText("Items").exists());
        assertTrue($(Span.class).withText("Items: 0").exists());
        assertFalse($(ListItem.class).exists());
        assertTrue($(TextField.class).withProperty("label", "Item").exists());
        assertEquals("", $(TextField.class).single().getValue());
    }

    @Test
    void addAppendsItemClearsFieldAndUpdatesCount() {
        addItem("Milk");
        assertTrue($(ListItem.class).withText("Milk").exists());
        assertEquals("", $(TextField.class).single().getValue());
        assertTrue($(Span.class).withText("Items: 1").exists());

        addItem("Eggs");
        assertEquals(2, $(ListItem.class).size());
        assertTrue($(Span.class).withText("Items: 2").exists());
    }

    @Test
    void blankAddIsRejected() {
        addItem("");
        addItem("   ");
        assertFalse($(ListItem.class).exists());
        assertTrue($(Span.class).withText("Items: 0").exists());
        assertTrue($(TextField.class).single().isInvalid());
    }

    @Test
    void duplicateTextIsAddedEachTime() {
        addItem("Milk");
        addItem("Milk");
        assertEquals(2, $(ListItem.class).size());
        assertTrue($(Span.class).withText("Items: 2").exists());
    }

    @Test
    void clearRemovesAllItems() {
        addItem("Milk");
        addItem("Eggs");
        $(Button.class).withText("Clear").single().click();
        assertFalse($(ListItem.class).exists());
        assertTrue($(Span.class).withText("Items: 0").exists());

        addItem("Bread");
        assertTrue($(ListItem.class).withText("Bread").exists());
        assertTrue($(Span.class).withText("Items: 1").exists());
    }

    private void addItem(String value) {
        $(TextField.class).single().setValue(value);
        $(Button.class).withText("Add").single().click();
    }
}
